package com.bank.txn.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "transactions")
public class Transaction {
    @Id private String id;
    private String reference;
    private BigDecimal amount;
    private String status;
    @Column(name = "created_at", updatable = false) private Instant createdAt;
    @Column(name = "updated_at") private Instant updatedAt;

    protected Transaction() {}
    public Transaction(String id, BigDecimal amount) {
        this.id = id; this.amount = amount; this.status = "PENDING";
    }

    @PrePersist   // fires right before INSERT
    void onCreate() {
        this.createdAt = Instant.now();
        this.reference = "TXN-" + UUID.randomUUID().toString().substring(0, 8);
    }

    @PostPersist  // fires after INSERT (id now in DB)
    void afterCreate() {
        System.out.println("INFO  Transaction persisted: " + reference);
    }

    @PreUpdate    // fires before UPDATE, only if something changed
    void onUpdate() { this.updatedAt = Instant.now(); }

    public void setStatus(String s) { this.status = s; }
    public String getReference() { return reference; }
}
