package com.bank.txn.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id private String id;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;
    @Column(name = "hold_amount") private BigDecimal holdAmount;

    @Transient private BigDecimal availableBalance;  // not stored

    protected Account() {}

    @PostLoad   // fires after entity loaded from DB
    void computeDerived() {
        this.availableBalance = balance.subtract(holdAmount);
    }

    @PreRemove  // fires before DELETE
    void onDelete() {
        System.out.println("SEVERE  Account about to be removed: " + id);
    }

    public BigDecimal getAvailableBalance() { return availableBalance; }
    public String getId() { return id; }
}
