package com.bank.txn.service;

import com.bank.txn.model.Transaction;
import com.bank.txn.repository.TxnRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Slf4j
@Service
@RequiredArgsConstructor
public class TxnService {
    private final TxnRepository repo;

    @Transactional
    public Transaction create(String id, BigDecimal amount) {
        Transaction t = new Transaction(id, amount);  // reference/createdAt NOT set yet
        Transaction saved = repo.save(t);             // @PrePersist sets them
        log.info("Created {} with ref {}", id, saved.getReference());
        return saved;
    }

    @Transactional
    public void settle(String id) {
        Transaction t = repo.findById(id).orElseThrow();
        t.setStatus("SETTLED");  // dirty → @PreUpdate fires on flush
    }
}
